"""Core data models for the RAG pipeline."""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict


@dataclass
class Document:
    """A source document plus its structured metadata (e.g. category, tags,
    year, author, region). Metadata is used for pre-retrieval filtering and
    post-retrieval provenance."""
    doc_id: str
    title: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass
class Chunk:
    """A retrievable text unit. Carries the full metadata of its parent
    document plus chunk-level fields (doc_id, title, chunk_index)."""
    chunk_id: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)

    @property
    def doc_id(self) -> str:
        return str(self.metadata.get("doc_id", ""))

    @property
    def title(self) -> str:
        return str(self.metadata.get("title", ""))

    @property
    def source_label(self) -> str:
        cat = self.metadata.get("category", "uncategorized")
        ver = self.metadata.get("version", "")
        suffix = f" (v{ver})" if ver else ""
        return f"{self.title} [{cat}]{suffix}"


@dataclass
class RetrievalResult:
    """One ranked hit: chunk + fine-grained scores."""
    chunk: Chunk
    scores: Dict[str, float] = field(default_factory=dict)
    rank: int = 0

    @property
    def combined_score(self) -> float:
        return float(self.scores.get("combined", 0.0))

"""Dense vectorization.

Production systems normally use a semantic model such as
text-embedding-ada-002, all-MiniLM-L6-v2 or bge-large. This module provides a
deterministic, dependency-free stand-in (feature hashing + IDF weighting over
tokens and word bigrams) so the *pipeline* runs anywhere end to end, plus a
single obvious extension point: swap `vectorizer.embed` for any embedding
model. Cosine similarity over these vectors behaves like weighted lexical
overlap, which is adequate to demonstrate filtering + ranking semantics.
"""
from __future__ import annotations

import math
import re
import zlib
from collections import Counter
from typing import List

_TOKEN_RE = re.compile(r"[a-z0-9]+")


def tokenize(text: str) -> List[str]:
    return _TOKEN_RE.findall(text.lower())


def _bigrams(tokens: List[str]) -> List[str]:
    return [" ".join(p) for p in zip(tokens, tokens[1:])]


class HashedVectorizer:
    def __init__(self, dim: int = 4096):
        self.dim = dim
        self.n = 0                       # number of fitted texts (chunks)
        self.df = {}                     # feature -> #chunks containing it
        self.idf = {}                    # feature -> weight

    def fit(self, texts: List[str]) -> "HashedVectorizer":
        self.n = 0
        self.df = {}
        for text in texts:
            self.n += 1
            for feat in set(self._features(text)):
                self.df[feat] = self.df.get(feat, 0) + 1
        for feat, df in self.df.items():
            self.idf[feat] = math.log((self.n - df + 0.5) / (df + 0.5) + 1.0)
        return self

    def embed(self, text: str) -> List[float]:
        if not self.idf:
            raise RuntimeError("vectorizer.fit() must be called before embed()")
        vec = [0.0] * self.dim
        counts = Counter(self._features(text))
        default_idf = math.log(self.n + 1.0)   # unseen query terms are strong
        for feat, c in counts.items():
            w = self.idf.get(feat, default_idf) * (1.0 + math.log(c))
            i = zlib.crc32(feat.encode("utf-8")) % self.dim
            sign = 1 if (zlib.crc32(("SIGN:" + feat).encode("utf-8")) & 1) else -1
            vec[i] += sign * w
        norm = math.sqrt(sum(x * x for x in vec))
        if norm > 0:
            vec = [x / norm for x in vec]
        return vec

    @staticmethod
    def _features(text: str) -> List[str]:
        toks = tokenize(text)
        return toks + _bigrams(toks)


def cosine(a: List[float], b: List[float]) -> float:
    return sum(x * y for x, y in zip(a, b))

"""Vector store + metadata filtering index.

MetadataIndex is an inverted index over metadata *values*: for every
field -> value we keep a posting set of chunk ids. Retrieval therefore
*pre-filters the candidate set with set intersections* and only scores what
survives the filter (the same pattern used with Pinecone/Chroma metadata
predicates, but implemented in-process here).

Supported filter expressions (JSON-able):
    {"category": "security"}                       equality / list membership
    {"tags": {"$in": ["launch", "beta"]}}          membership in list field
    {"year": {"$gte": 2024, "$lte": 2025}}         numeric range (any op)
    {"$and": [ {expr}, {expr} ]}, {"$or": [...]}
    nested {field: {op: arg}} combine with implicit AND
A missing/empty filter matches everything (None == unrestricted).
"""
from __future__ import annotations

import bisect
from typing import Any, Dict, List, Optional, Set, Union

from models import Chunk

_NUMERIC_OPS = {"$gte", "$gt", "$lte", "$lt"}
_HIGH = "\uffff"   # sorts after any ASCII chunk id


class MetadataIndex:
    def __init__(self) -> None:
        self._eq: Dict[str, Dict[Any, Set[str]]] = {}
        self._num: Dict[str, List[tuple]] = {}

    def add(self, chunk_id: str, metadata: Dict[str, Any]) -> None:
        for field, val in metadata.items():
            if val is None or isinstance(val, bool):
                continue
            values = val if isinstance(val, (list, tuple, set)) else (val,)
            for v in values:
                if v is None or isinstance(v, bool):
                    continue
                if isinstance(v, (int, float)):
                    self._num.setdefault(field, []).append((float(v), chunk_id))
                if isinstance(v, (int, float, str)):
                    self._eq.setdefault(field, {}).setdefault(v, set()).add(chunk_id)

    def finalize(self) -> None:
        for lst in self._num.values():
            lst.sort(key=lambda t: t[0])

    def fields(self) -> List[str]:
        return sorted(set(self._eq) | set(self._num))

    # -- filtering ----------------------------------------------------------
    def evaluate(self, expr: Optional[dict]) -> Optional[Set[str]]:
        """Return None when unrestricted, else the matching chunk-id set."""
        if not expr:
            return None
        if not isinstance(expr, dict):
            raise TypeError("filter must be a dict")
        keys = set(expr)
        if "$or" in keys or "$and" in keys:
            acc: Optional[Set[str]] = None
            for sub in expr.get("$or", []):
                s = self.evaluate(sub)
                acc = s if acc is None else (acc | s)
            for sub in expr.get("$and", []):
                s = self.evaluate(sub)
                if s is not None:
                    acc = s if acc is not None else s
                    # note: intentionally recomputed below for correctness
            # recompute intersection semantics cleanly:
            acc = None
            for sub in expr.get("$and", []):
                s = self.evaluate(sub)
                acc = s if acc is None else (acc & s)
            return acc
        acc: Optional[Set[str]] = None
        for field, cond in expr.items():
            s = self._match_field(field, cond)
            acc = s if acc is None else (acc & s)
        return acc

    def _match_field(self, field: str, cond: Any) -> Set[str]:
        eq = self._eq.get(field, {})
        if isinstance(cond, dict) and any(k.startswith("$") for k in cond):
            acc: Optional[Set[str]] = None
            for op, arg in cond.items():
                s = self._op_set(field, op, arg)
                acc = s if acc is None else (acc & s)
            return acc if acc is not None else set()
        if isinstance(cond, (list, tuple, set)):      # field IN [a, b, ...]
            out: Set[str] = set()
            for v in cond:
                out |= eq.get(v, set())
            return out
        return eq.get(cond, set())                    # equality / membership

    def _op_set(self, field: str, op: str, arg: Any) -> Set[str]:
        eq = self._eq.get(field, {})
        if op == "$in":
            out: Set[str] = set()
            vals = arg if isinstance(arg, (list, tuple, set)) else [arg]
            for v in vals:
                out |= eq.get(v, set())
            return out
        if op == "$eq":
            return eq.get(arg, set())
        if op in _NUMERIC_OPS:
            nums = self._num.get(field, [])
            if not nums:
                return set()
            num = float(arg)
            if op == "$gte":
                idx = bisect.bisect_left(nums, (num, ""))
                return {cid for _, cid in nums[idx:]}
            if op == "$gt":
                idx = bisect.bisect_right(nums, (num, _HIGH))
                return {cid for _, cid in nums[idx:]}
            if op == "$lte":
                idx = bisect.bisect_right(nums, (num, _HIGH))
                return {cid for _, cid in nums[:idx]}
            if op == "$lt":
                idx = bisect.bisect_left(nums, (num, ""))
                return {cid for _, cid in nums[:idx]}
        raise ValueError(f"unsupported filter operator: {op}")


class VectorStore:
    """Chunk text + embeddings + metadata index."""

    def __init__(self) -> None:
        self.chunks: Dict[str, Chunk] = {}
        self.vectors: Dict[str, List[float]] = {}
        self.meta = MetadataIndex()

    def add_chunks(self, chunks, vectorizer) -> None:
        for ch in chunks:
            self.chunks[ch.chunk_id] = ch
            self.vectors[ch.chunk_id] = vectorizer.embed(ch.text)
            self.meta.add(ch.chunk_id, ch.metadata)
        self.meta.finalize()

    @property
    def size(self) -> int:
        return len(self.chunks)


# ---------------------------------------------------------------------------
# Independent metadata matcher used to *validate* filter results. It mirrors
# MetadataIndex semantics without sharing code, so demo assertions double-check
# the inverted-index implementation against the original filter expression.
# ---------------------------------------------------------------------------
def filter_matches(metadata: Dict[str, Any], expr: Optional[dict]) -> bool:
    if not expr:
        return True
    if not isinstance(expr, dict):
        raise TypeError("filter must be a dict")
    if "$or" in expr:
        return any(filter_matches(metadata, sub) for sub in expr["$or"])
    if "$and" in expr:
        return all(filter_matches(metadata, sub) for sub in expr["$and"])
    return all(_field_matches(metadata, f, c) for f, c in expr.items())


def _field_matches(metadata: Dict[str, Any], field: str, cond) -> bool:
    val = metadata.get(field)
    if isinstance(cond, dict) and any(k.startswith("$") for k in cond):
        for op, arg in cond.items():
            if not _op_matches(val, op, arg):
                return False
        return True
    return _eq_matches(val, cond)


def _eq_matches(val, wanted) -> bool:
    if val is None:
        return False
    if isinstance(val, (list, tuple, set)):
        return any(v == wanted for v in val)
    return val == wanted


def _op_matches(val, op: str, arg) -> bool:
    if val is None:
        return False
    vals = val if isinstance(val, (list, tuple, set)) else [val]
    if op in ("$eq", "$in"):
        args = arg if isinstance(arg, (list, tuple, set)) else [arg]
        return any(v in args for v in vals)
    if op in _NUMERIC_OPS:
        for v in vals:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                continue
            if op == "$gte" and v >= arg:
                return True
            if op == "$gt" and v > arg:
                return True
            if op == "$lte" and v <= arg:
                return True
            if op == "$lt" and v < arg:
                return True
        return False
    raise ValueError(f"unsupported filter operator: {op}")

"""Retrieval: hybrid relevance ranking over a metadata-filtered candidate set.

Ranking pipeline:
  1. Resolve the metadata filter -> candidate chunk-id set (before scoring).
  2. Score every candidate with BOTH dense cosine similarity and BM25.
  3. Min-max normalize each score family, fuse into one relevance score.
  4. Optionally rerank the top candidates with Maximal Marginal Relevance
     (diversity), trading relevance vs. redundancy.
"""
from __future__ import annotations

import math
from typing import Dict, List, Optional, Set, Tuple

from embeddings import cosine, tokenize
from models import RetrievalResult
from vectorstore import VectorStore

_K1, _B = 1.5, 0.75


class BM25Index:
    """Classic sparse scoring; complements dense vectors (hybrid retrieval)."""

    def __init__(self) -> None:
        self.n = 0
        self.df: Dict[str, int] = {}
        self.postings: Dict[str, Set[str]] = {}
        self.doc_tokens: Dict[str, List[str]] = {}
        self.doc_len: Dict[str, int] = {}
        self.avgdl = 1.0

    def add(self, chunk_id: str, text: str) -> None:
        toks = tokenize(text)
        self.doc_tokens[chunk_id] = toks
        self.doc_len[chunk_id] = len(toks)
        for t in set(toks):
            self.df[t] = self.df.get(t, 0) + 1
            self.postings.setdefault(t, set()).add(chunk_id)
        self.n += 1

    def finalize(self) -> None:
        self.avgdl = sum(self.doc_len.values()) / max(1, self.n)

    def rank(self, query_toks: List[str], candidates: Set[str]) -> Dict[str, float]:
        scores: Dict[str, float] = {}
        q_terms = set(query_toks)
        for cid in candidates:
            toks = self.doc_tokens.get(cid)
            if not toks:
                continue
            dl = len(toks)
            s = 0.0
            for t in q_terms:
                if t not in self.postings:
                    continue
                tf = toks.count(t)
                if tf == 0:
                    continue
                df = self.df[t]
                idf = math.log((self.n - df + 0.5) / (df + 0.5) + 1.0)
                denom = tf + _K1 * (1 - _B + _B * dl / self.avgdl)
                s += idf * (tf * (_K1 + 1)) / denom
            if s > 0:
                scores[cid] = s
        return scores


def _minmax(scores: Dict[str, float]) -> Dict[str, float]:
    if not scores:
        return {}
    vals = list(scores.values())
    lo, hi = min(vals), max(vals)
    rng = hi - lo
    if rng <= 1e-12:
        return {k: 1.0 for k in scores}
    return {k: (v - lo) / rng for k, v in scores.items()}


class Retriever:
    def __init__(self, store: VectorStore, vectorizer,
                 dense_weight: float = 0.65,
                 mmr_lambda: float = 0.7,
                 bm25_weight: Optional[float] = None):
        self.store = store
        self.v = vectorizer
        self.dense_weight = dense_weight
        self.mmr_lambda = mmr_lambda
        self.bm25_weight = bm25_weight if bm25_weight is not None else 1.0 - dense_weight
        self.bm25 = BM25Index()
        for cid, chunk in store.chunks.items():
            self.bm25.add(cid, chunk.text)
        self.bm25.finalize()

    # -- public API ---------------------------------------------------------
    def search(self, query: str, filt: Optional[dict] = None, k: int = 4,
               fetch_mult: int = 3, use_mmr: bool = False
               ) -> Tuple[List[RetrievalResult], dict]:
        qv = self.v.embed(query)
        q_toks = tokenize(query)
        total = self.store.size

        restricted = self.store.meta.evaluate(filt)
        candidates = (set(self.store.chunks) if restricted is None
                      else set(self.store.chunks) & restricted)
        stats = {
            "total_chunks": total,
            "candidate_chunks": len(candidates),
            "filter_fields": sorted(filt) if filt else [],
            "query_terms": q_toks,
        }
        if not candidates:
            return [], stats

        dense_raw = {cid: cosine(qv, self.store.vectors[cid]) for cid in candidates}
        bm_raw = self.bm25.rank(q_toks, candidates)
        d_n = _minmax(dense_raw)
        b_n = _minmax(bm_raw)
        wd, wb = self.dense_weight, self.bm25_weight
        combined = {cid: wd * d_n.get(cid, 0.0) + wb * b_n.get(cid, 0.0)
                    for cid in candidates}

        # primary ordering: fused relevance (ties broken by dense cosine)
        pool = sorted(combined, key=lambda c: (combined[c], dense_raw[c]),
                      reverse=True)
        fetch = min(len(pool), max(k, k * fetch_mult))
        pool = pool[:fetch]

        if use_mmr and k > 1:
            final_ids = self._mmr(pool, combined, k)
        else:
            final_ids = pool[:k]

        results: List[RetrievalResult] = []
        for i, cid in enumerate(final_ids, start=1):
            results.append(RetrievalResult(
                chunk=self.store.chunks[cid],
                rank=i,
                scores={
                    "combined": combined[cid],
                    "dense": dense_raw[cid],
                    "dense_norm": d_n.get(cid, 0.0),
                    "bm25": bm_raw.get(cid, 0.0),
                    "bm25_norm": b_n.get(cid, 0.0),
                },
            ))
        return results, stats

    # -- MMR reranking ------------------------------------------------------
    def _mmr(self, pool: List[str], combined: Dict[str, float], k: int
             ) -> List[str]:
        lam = self.mmr_lambda
        chosen: List[str] = []
        remaining = list(pool)
        while len(chosen) < k and remaining:
            best, best_key = None, None
            for cid in remaining:
                sim = 0.0
                if chosen:
                    sim = max(cosine(self.store.vectors[cid],
                                     self.store.vectors[s]) for s in chosen)
                    sim = max(0.0, sim)
                val = lam * combined[cid] - (1.0 - lam) * sim
                key = (val, combined[cid])
                if best_key is None or key > best_key:
                    best_key, best = key, cid
            chosen.append(best)
            remaining.remove(best)
        return chosen

"""Grounded answer generation.

`GroundedSynthesizer` has two modes:
  * LLM mode: plug in any callable (e.g. an OpenAI chat client) that turns a
    strict "use only this context" prompt into an answer with citations.
  * Offline mode (used by the demo, no network): an extractive, sentence-level
    grounded summary of the retrieved passages with [n] citations. This keeps
    the demo runnable anywhere while preserving the RAG grounding contract:
    every claim in the answer maps to a retrieved chunk.
"""
from __future__ import annotations

import re
from typing import Callable, Dict, List, Optional

from embeddings import tokenize
from models import RetrievalResult

_SENT_RE = re.compile(r"(?<=[.!?])\s+(?=[A-Z0-9])")


def _sentences(text: str) -> List[str]:
    parts = [p.strip() for p in _SENT_RE.split(text) if p.strip()]
    return parts or ([text.strip()] if text.strip() else [])


def _build_prompt(question: str, results: List[RetrievalResult]) -> str:
    blocks = []
    for i, r in enumerate(results, start=1):
        blocks.append(f"[{i}] {r.chunk.source_label}\n{r.chunk.text}")
    context = "\n\n".join(blocks)
    return (
        "Answer the question using ONLY the context passages below. "
        "Cite every passage you rely on as [1], [2], etc. If the context does "
        "not contain the answer, reply with exactly: Insufficient context.\n\n"
        f"Context:\n{context}\n\nQuestion: {question}\n\nAnswer:"
    )


class GroundedSynthesizer:
    def __init__(self, vectorizer=None, llm: Optional[Callable[[str], str]] = None,
                 top_sentences: int = 4, max_chars: int = 900):
        self.v = vectorizer
        self.llm = llm
        self.top_sentences = top_sentences
        self.max_chars = max_chars

    def synthesize(self, question: str, results: List[RetrievalResult]) -> dict:
        if not results:
            return {"answer": "No matching context found.",
                    "confidence": 0.0, "sources": [], "mode": "none"}
        if self.llm is not None:
            answer = self.llm(_build_prompt(question, results))
            return {"answer": answer,
                    "confidence": self._confidence(results, list(range(1, len(results) + 1))),
                    "sources": self._sources(results), "mode": "llm"}

        # offline grounded-extractive mode
        q_set = set(tokenize(question))
        default_idf = math_ln(self.v.n + 1.0) if self.v else 1.0
        idf = self.v.idf if self.v else {}

        # sentence candidates: (score, citation_no, sentence)
        cands: List[tuple] = []
        for res in results:
            for sent in _sentences(res.chunk.text):
                st = set(tokenize(sent))
                score = sum(idf.get(t, default_idf) for t in q_set if t in st)
                if score > 0:
                    cands.append((score, res.rank, sent))
        cands.sort(key=lambda t: t[0], reverse=True)

        used_chunks: List[int] = []
        per_chunk = {}
        answer_parts: List[str] = []
        budget = 0
        for score, cit, sent in cands:
            if len(used_chunks) >= self.top_sentences and len(used_chunks) >= len(results):
                pass
            if len(answer_parts) >= self.top_sentences:
                break
            if per_chunk.get(cit, 0) >= 2:      # avoid single-chunk dominance
                continue
            if budget + len(sent) > self.max_chars and answer_parts:
                break
            per_chunk[cit] = per_chunk.get(cit, 0) + 1
            used_chunks.append(cit)
            budget += len(sent) + 4
            answer_parts.append(f"{sent} [{cit}]")

        answer = " ".join(answer_parts) if answer_parts else (
            "The retrieved context does not contain sentences clearly "
            "responsive to this question.")
        return {"answer": answer,
                "confidence": self._confidence(results, used_chunks),
                "sources": self._sources(results), "mode": "offline-extractive"}

    # -- helpers ------------------------------------------------------------
    def _confidence(self, results: List[RetrievalResult],
                    used: List[int]) -> float:
        if not used:
            return 0.0
        ranks = set(used)
        conf = [r.combined_score for r in results if r.rank in ranks]
        if not conf:
            return 0.0
        return round(max(0.0, min(1.0, sum(conf) / len(conf))), 4)

    def _sources(self, results: List[RetrievalResult]) -> List[dict]:
        out = []
        for r in results[:5]:
            m = r.chunk.metadata
            out.append({
                "doc_id": r.chunk.doc_id,
                "chunk_id": r.chunk.chunk_id,
                "title": r.chunk.title,
                "category": m.get("category"),
                "year": m.get("year"),
                "tags": m.get("tags"),
                "excerpt": (r.chunk.text[:150] + "..." if len(r.chunk.text) > 150
                            else r.chunk.text),
            })
        return out


def math_ln(x: float) -> float:
    import math
    return math.log(x)

