def _print_divider(title: str) -> None:
    print("\n" + "=" * 72)
    print(title)
    print("=" * 72)


def main() -> None:
    print("Building RAG system over demo corpus...")
    rag = RagSystem()
    added = rag.add_documents(demo_corpus(), chunk=True)
    print("Indexed %d chunked documents.\n" % added)

    # --- Demo 1: metadata FILTER + relevance ranking ---------------------
    query = "Which database stores embedding vectors and searches by similarity?"
    filter_spec = {"category": "database", "year": {"$gte": 2021}}
    prefer = {
        "tags": {"value": ["vector", "embeddings", "metadata"], "weight": 0.6},
        "quality": {"value": 5, "weight": 0.4},
    }

    _print_divider("Demo 1: metadata filter (category=database, year>=2021)\n"
                   "         + relevance ranking boosted by tags/quality preferences")
    answer = rag.answer(query, filter_spec=filter_spec, prefer=prefer, k=3)
    print("Query: %s" % answer.query)
    print("Filter: %s" % answer.filter_spec)
    print("Prefer (ranking boost): %s\n" % answer.prefer)
    for r in answer.results:
        print(r.describe())
        print("-" * 72)
    print("\nANSWER (fallback, no generator):\n%s" % answer.answer_text)

    # --- Demo 2: filter excludes everything -------------------------------
    _print_divider("Demo 2: same query, filter only old 2020 documents")
    old = rag.answer(
        query,
        filter_spec={"category": "database", "year": {"$lt": 2021}},
        k=3,
    )
    print("Filter: %s" % old.filter_spec)
    print("Matched %d documents." % len(old.results))
    for r in old.results:
        print(r.describe())

    # --- Demo 3: metadata-only ranking (no free-text query) ---------------
    _print_divider("Demo 3: metadata-only ranking (no query text):\n"
                   "         prefer high-quality 2024 docs tagged metadata")
    by_meta = rag.retrieve(
        text="",
        prefer={
            "year": {"value": "2024", "weight": 0.3},
            "quality": {"value": 5, "weight": 0.3},
            "tags": {"value": ["metadata"], "weight": 0.4},
        },
        k=3,
    )
    for r in by_meta:
        print(r.describe())
        print("-" * 72)

    # --- Demo 4: pluggable generator --------------------------------------
    _print_divider("Demo 4: pluggable generator (a deterministic 'LLM')")

    def fake_llm(prompt: str) -> str:
        # Deterministic stand-in for an LLM: mirror the prompt with a note.
        return (
            "Grounded answer (simulated LLM). The context passages above "
            "already contain the retrieved metadata and text; a real model "
            "would synthesize from them and cite [n] tags."
        )

    rag2 = RagSystem(generator=fake_llm)
    rag2.add_documents(demo_corpus(), chunk=True)
    gen_answer = rag2.answer(
        "What should chunking do and which metadata should every chunk carry?",
        filter_spec={"category": "rag"},
        k=2,
    )
    print("Query: %s\nFilter: %s\n" % (gen_answer.query, gen_answer.filter_spec))
    print("ANSWER (generated):\n%s" % gen_answer.answer_text)
    print("\nAll demos completed successfully.")


if __name__ == "__main__":
    main()

"""Core data models for the RAG pipeline."""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict


@dataclass
class Document:
    """A source document plus its structured metadata (e.g. category, tags,
    year, author, region). Metadata is used for pre-retrieval filtering and
    post-retrieval provenance."""
    doc_id: str
    title: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass
class Chunk:
    """A retrievable text unit. Carries the full metadata of its parent
    document plus chunk-level fields (doc_id, title, chunk_index)."""
    chunk_id: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)

    @property
    def doc_id(self) -> str:
        return str(self.metadata.get("doc_id", ""))

    @property
    def title(self) -> str:
        return str(self.metadata.get("title", ""))

    @property
    def source_label(self) -> str:
        cat = self.metadata.get("category", "uncategorized")
        ver = self.metadata.get("version", "")
        suffix = f" (v{ver})" if ver else ""
        return f"{self.title} [{cat}]{suffix}"


@dataclass
class RetrievalResult:
    """One ranked hit: chunk + fine-grained scores."""
    chunk: Chunk
    scores: Dict[str, float] = field(default_factory=dict)
    rank: int = 0

    @property
    def combined_score(self) -> float:
        return float(self.scores.get("combined", 0.0))
